FUNCTION_BLOCK FB_RoboticFSW_AdvControl
VAR_INPUT
    (* Required: at least 4-8 physical inputs with types and comments *)
    bEnable                 : BOOL;     (* System enable signal for FSW operation *)
    bEmergencyStop          : BOOL;     (* Safety relay OK signal (E-Stop loop closed) *)
    rActualSpindleSpeed     : REAL;     (* Feedback from spindle encoder (RPM) *)
    rPlungeForceZ           : REAL;     (* Z-axis force feedback from load cell (kN) *)
    rToolTempCelsius        : REAL;     (* Pyrometer reading of tool temperature (deg C) *)
    rAcousticEmission       : REAL;     (* High-frequency AE sensor for tool wear monitoring (mV) *)
    rTargetWeldSpeed        : REAL;     (* Desired TCP (Tool Center Point) feed rate (mm/s) *)
    rTargetPlungeForce      : REAL;     (* Desired Z-axis plunge force (kN) *)
END_VAR
VAR_OUTPUT
    (* Required: at least 3-6 outputs with types and comments *)
    bSystemReady            : BOOL;     (* System ready status for motion controller *)
    rCmdSpindleSpeed        : REAL;     (* Control signal to spindle VFD/Servo (RPM) *)
    rCmdZAxisPosition       : REAL;     (* Control signal for Z-axis position offset (mm) for force control *)
    bToolWearAlarm          : BOOL;     (* Fault alarm output - tool fracture or critical wear *)
    bForceToleranceAlarm    : BOOL;     (* Plunge force deviation exceeds allowed bandwidth *)
    iOperationState         : INT;      (* Current operation state of the FSW block *)
END_VAR
VAR
    (* Internal state variables *)
    iState                  : INT := 0;
    tDwellTimer             : TON;
    tCoolDownTimer          : TON;
    rSpindlePID_Kp          : REAL := 0.25;
    rSpindlePID_Ki          : REAL := 0.05;
    rForcePID_Kp            : REAL := 0.012;
    rForcePID_Ki            : REAL := 0.003;
    rForceErrorIntegral     : REAL := 0.0;
    rForceError             : REAL := 0.0;
    rSpindleErrorIntegral   : REAL := 0.0;
    rSpindleError           : REAL := 0.0;

    (* Constants *)
    MAX_Z_OFFSET            : REAL := 5.0;  (* Max allowable Z correction in mm *)
    MIN_Z_OFFSET            : REAL := -5.0; (* Min allowable Z correction in mm *)
    MAX_SPINDLE_SPEED       : REAL := 3000.0;
    MAX_AE_THRESHOLD        : REAL := 850.0; (* AE mV threshold for fracture *)
END_VAR

(* === MAIN LOGIC === *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    bToolWearAlarm := FALSE;
    bForceToleranceAlarm := FALSE;
    rCmdSpindleSpeed := 0.0;
    rCmdZAxisPosition := 0.0;
    iState := 0;
    iOperationState := 0;
    RETURN;
END_IF;

(* Acoustic Emission Monitoring for Tool Wear/Fracture *)
IF rAcousticEmission > MAX_AE_THRESHOLD THEN
    bToolWearAlarm := TRUE;
    iState := 999; (* FAULT STATE *)
END_IF;

CASE iState OF
    0: (* IDLE *)
        bSystemReady := TRUE;
        rCmdSpindleSpeed := 0.0;
        rCmdZAxisPosition := 0.0;
        iOperationState := 0;

        IF bEnable AND NOT bToolWearAlarm THEN
            bSystemReady := FALSE;
            iState := 10;
        END_IF;

    10: (* SPINDLE SPIN-UP *)
        iOperationState := 10;
        (* Open loop ramp up for spindle to basic operating speed *)
        rCmdSpindleSpeed := rCmdSpindleSpeed + 50.0;
        IF rCmdSpindleSpeed >= 1500.0 THEN
            rCmdSpindleSpeed := 1500.0;
            IF rActualSpindleSpeed > 1450.0 THEN
                iState := 20;
            END_IF;
        END_IF;

    20: (* PLUNGE & DWELL *)
        iOperationState := 20;
        (* Z-Axis Force Control PID *)
        rForceError := rTargetPlungeForce - rPlungeForceZ;
        rForceErrorIntegral := rForceErrorIntegral + rForceError;

        (* Anti-windup *)
        IF rForceErrorIntegral > 100.0 THEN rForceErrorIntegral := 100.0; END_IF;
        IF rForceErrorIntegral < -100.0 THEN rForceErrorIntegral := -100.0; END_IF;

        rCmdZAxisPosition := (rForceError * rForcePID_Kp) + (rForceErrorIntegral * rForcePID_Ki);

        (* Clamp Z output *)
        IF rCmdZAxisPosition > MAX_Z_OFFSET THEN rCmdZAxisPosition := MAX_Z_OFFSET; END_IF;
        IF rCmdZAxisPosition < MIN_Z_OFFSET THEN rCmdZAxisPosition := MIN_Z_OFFSET; END_IF;

        (* Dwell condition check: Force stable and temp rising *)
        IF ABS(rForceError) < 0.5 AND rToolTempCelsius > 350.0 THEN
            tDwellTimer(IN := TRUE, PT := T#3S);
            IF tDwellTimer.Q THEN
                tDwellTimer(IN := FALSE);
                iState := 30;
            END_IF;
        ELSE
            tDwellTimer(IN := FALSE);
        END_IF;

    30: (* TRAVERSE WELDING (FSW) *)
        iOperationState := 30;

        (* Spindle Speed Dynamic Compensation PID based on Temp and Force *)
        (* Maintain heat generation through constant friction via speed modulation *)
        rSpindleError := rTargetPlungeForce - rPlungeForceZ; 
        rSpindleErrorIntegral := rSpindleErrorIntegral + rSpindleError;

        rCmdSpindleSpeed := 1500.0 + (rSpindleError * rSpindlePID_Kp) + (rSpindleErrorIntegral * rSpindlePID_Ki);
        IF rCmdSpindleSpeed > MAX_SPINDLE_SPEED THEN rCmdSpindleSpeed := MAX_SPINDLE_SPEED; END_IF;

        (* Z-Axis Force Control PID active during traverse *)
        rForceError := rTargetPlungeForce - rPlungeForceZ;
        rForceErrorIntegral := rForceErrorIntegral + rForceError;
        rCmdZAxisPosition := (rForceError * rForcePID_Kp) + (rForceErrorIntegral * rForcePID_Ki);

        IF ABS(rForceError) > 2.5 THEN
            bForceToleranceAlarm := TRUE;
        ELSE
            bForceToleranceAlarm := FALSE;
        END_IF;

        IF NOT bEnable THEN
            iState := 40;
        END_IF;

    40: (* RETRACT & SPIN-DOWN *)
        iOperationState := 40;
        rCmdZAxisPosition := rCmdZAxisPosition - 0.1; (* Ramp Z up *)
        IF rCmdZAxisPosition < -2.0 THEN
            rCmdSpindleSpeed := 0.0;
            tCoolDownTimer(IN := TRUE, PT := T#5S);
            IF tCoolDownTimer.Q THEN
                tCoolDownTimer(IN := FALSE);
                iState := 0;
            END_IF;
        END_IF;

    999: (* FAULT HANDLING *)
        iOperationState := 999;
        rCmdSpindleSpeed := 0.0;
        rCmdZAxisPosition := 0.0;
        bSystemReady := FALSE;
        IF NOT bToolWearAlarm AND NOT bForceToleranceAlarm AND bEnable=FALSE THEN
            iState := 0;
        END_IF;

END_CASE;

END_FUNCTION_BLOCK
